import{_ as a,o as t,c as s,ah as n}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Passer à une licence","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"admission/ecoles/passage-licence.md","filePath":"src/admission/ecoles/passage-licence.md"}'),i={name:"admission/ecoles/passage-licence.md"};function l(r,e,o,u,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="passer-a-une-licence" tabindex="-1">Passer à une licence <a class="header-anchor" href="#passer-a-une-licence" aria-label="Permalink to &quot;Passer à une licence&quot;">​</a></h1><p>Une fois convaincus par la version gratuite ou par la démonstration complète, le passage à une licence payante n&#39;est pas une opération que vous effectuez seuls en ligne : c&#39;est une étape <strong>accompagnée par l&#39;équipe commerciale edPage</strong>, qui échange avec vous sur vos besoins réels avant de mettre en place la licence adaptée à votre établissement.</p><h2 id="comment-se-passe-l-achat" tabindex="-1">Comment se passe l&#39;achat <a class="header-anchor" href="#comment-se-passe-l-achat" aria-label="Permalink to &quot;Comment se passe l&#39;achat&quot;">​</a></h2><ol><li>Vous contactez l&#39;équipe edPage (ou c&#39;est elle qui vous recontacte, typiquement pendant ou à la fin de votre démonstration complète).</li><li>Ensemble, vous définissez les pôles dont votre établissement a besoin et la formule d&#39;hébergement qui vous convient.</li><li>L&#39;équipe edPage met en place la licence sur votre établissement depuis son panel interne.</li><li>Votre espace reflète immédiatement les pôles licenciés — plus besoin d&#39;attendre une mise à jour ou une réinstallation.</li></ol><p>Il n&#39;y a pas de paiement en ligne self-service pour l&#39;achat d&#39;une licence : c&#39;est volontaire, pour que chaque licence corresponde réellement à ce dont votre établissement a besoin plutôt qu&#39;à une offre figée choisie seul dans un formulaire.</p><h2 id="les-poles-disponibles-a-la-carte" tabindex="-1">Les pôles disponibles à la carte <a class="header-anchor" href="#les-poles-disponibles-a-la-carte" aria-label="Permalink to &quot;Les pôles disponibles à la carte&quot;">​</a></h2><p>ERA se licencie par pôle fonctionnel plutôt qu&#39;en bloc : vous choisissez ceux qui correspondent à vos besoins, ou l&#39;offre complète si vous préférez tout couvrir dès le départ. Les pôles couvrent, entre autres :</p><ul><li>la structure de l&#39;établissement et les admissions (au-delà du simple formulaire public déjà inclus gratuitement) ;</li><li>la vie académique (classes, emplois du temps, évaluations, présences, internat, infirmerie...) ;</li><li>les finances (frais de scolarité, encaissements, dépenses) ;</li><li>les relations familles (portail parent, portail élève) ;</li><li>le tableau de bord de pilotage.</li></ul><p>Le détail exact de ce que couvre chaque pôle et son tarif vous est communiqué par l&#39;équipe edPage au moment de la mise en place — il peut évoluer et n&#39;a pas vocation à être figé dans ce guide.</p><h2 id="les-deux-formules-d-hebergement" tabindex="-1">Les deux formules d&#39;hébergement <a class="header-anchor" href="#les-deux-formules-d-hebergement" aria-label="Permalink to &quot;Les deux formules d&#39;hébergement&quot;">​</a></h2><p>Une fois la licence achetée, votre établissement choisit entre deux formules d&#39;hébergement. Le choix n&#39;est pas anodin : il détermine qui gère concrètement votre serveur au quotidien.</p><h3 id="autonome-par-defaut" tabindex="-1">Autonome (par défaut) <a class="header-anchor" href="#autonome-par-defaut" aria-label="Permalink to &quot;Autonome (par défaut)&quot;">​</a></h3><p>C&#39;est la formule par défaut : votre établissement héberge lui-même son installation d&#39;ERA, sur son propre serveur. L&#39;équipe edPage vous accompagne pour la mise en place initiale (transfert de vos données d&#39;admission déjà saisies, activation de la licence sur votre serveur), mais l&#39;hébergement au quotidien — disponibilité, sauvegardes, maintenance technique — relève ensuite de votre établissement ou de son prestataire technique.</p><p>C&#39;est la formule adaptée aux établissements qui ont déjà (ou veulent avoir) la main sur leur infrastructure.</p><h3 id="cle-en-main-payant" tabindex="-1">Clé en main (payant) <a class="header-anchor" href="#cle-en-main-payant" aria-label="Permalink to &quot;Clé en main (payant)&quot;">​</a></h3><p>Avec cette formule, edPage continue d&#39;héberger votre établissement sur son infrastructure — exactement comme pendant votre inscription gratuite et votre démonstration, à ceci près que l&#39;accès en lecture-écriture reste ouvert en continu, sans limite de durée ni gel en lecture seule. Cette prise en charge de l&#39;hébergement est facturée en plus de la licence elle-même.</p><p>C&#39;est la formule adaptée aux établissements qui préfèrent ne pas gérer de serveur du tout et laisser cette responsabilité à edPage.</p><h3 id="ce-qui-change-concretement-pour-vous" tabindex="-1">Ce qui change concrètement pour vous <a class="header-anchor" href="#ce-qui-change-concretement-pour-vous" aria-label="Permalink to &quot;Ce qui change concrètement pour vous&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Autonome</th><th>Clé en main</th></tr></thead><tbody><tr><td>Qui héberge le serveur</td><td>Votre établissement</td><td>edPage</td></tr><tr><td>Coût d&#39;hébergement</td><td>Aucun (au-delà de votre propre infrastructure)</td><td>Facturé en plus de la licence</td></tr><tr><td>Mise en place initiale</td><td>Accompagnée par edPage (transfert des données, activation)</td><td>Prise en charge intégralement par edPage</td></tr><tr><td>Accès au quotidien</td><td>Identique — les pôles licenciés sont disponibles dans les deux cas</td><td>Identique — les pôles licenciés sont disponibles dans les deux cas</td></tr></tbody></table><p>Dans les deux cas, les pôles que vous avez licenciés fonctionnent de la même façon pour vos utilisateurs (admin, enseignants, secrétariat...) — seule la question de « qui s&#39;occupe du serveur » change.</p>',20)])])}const h=a(i,[["render",l]]);export{m as __pageData,h as default};
